# Rafael PEPT spherical diaphragm tanks (satsearch tank overview + PEPT-200 listing, 2026-11-08). The model number matches the sphere diameter in mm (PEPT-230 = 6 L sphere, 230 mm dia = 6.4 L), so diameters are DERIVED from the name.
for model, diameter, liters, mass, note in (("PEPT-200", 200, 4.2, 910, "Dry mass 0.91 +/-0.05 kg, 3.3 kg propellant, equatorial mount, qualification completed Dec 2024 (listing). Volume derived from the diameter."), ("PEPT-230", 230, 6.0, 1300, "6 L from the overview; mass ESTIMATE."), ("PEPT-260", 260, 9.3, 1800, "9.3 L from the overview; mass ESTIMATE."), ("PEPT-330", 330, 17.5, 3000, "17.5 L from the overview; mass ESTIMATE.")):
    PARTS.append(part("rafael_" + model.lower().replace("-", "_"), "Rafael " + model + " spherical diaphragm propellant tank (" + str(liters) + " L)", "propulsion", "tank", "Rafael Advanced Defense Systems", model, (diameter, diameter, diameter), mass, {"kind": "sphere", "diameter": diameter},
        source("derived", "https://satsearch.co/products/rafael-" + model.lower() + ("-propellant-tank" if model == "PEPT-200" else ""), "satsearch tank overview and PEPT listings", ["propulsion"], notes="Diameter DERIVED from the model number (PEPT-nnn = nnn mm sphere, consistent with the stated 6 L for PEPT-230). " + note + " EPDM diaphragm; hydrazine, ADN-based green propellant, IPA, water, GN2, GHe compatible."), vendor_country="Israel", distributors=["direct", "satsearch"], status="in_production", dimensions_note="derived from model number", mass_note="estimate" if model != "PEPT-200" else None,
        propulsion={"type": "propellant tank", "volume_L": liters, "expulsion": "EPDM elastomeric diaphragm", "propellants": ["hydrazine", "ADN-based green", "IPA", "water", "GN2", "GHe"], "mounting": "equatorial"}, cost=cost(basis="quote")))
